<script setup>
import { ref,watch,onMounted,onBeforeUnmount } from 'vue';
import { Crosshair,Hand,Flashlight,RotateCcw,Footprints,Map,BookOpen,Pause,ArrowDown,Target,Shield,Eye } from 'lucide-vue-next';
import {TorchGesture} from './torch-gesture.js';
import {LookGesture} from './look-gesture.js';
import {MoveGesture} from './move-gesture.js';
import { nativeFeedback } from './platform.js';
const props=defineProps({engine:Object,hud:Object});
const emit=defineEmits(['map','journal','pause']);
const knob=ref({x:0,y:0}),sprint=ref(false),crouch=ref(false),looking=ref(false);
watch(()=>props.hud.sprintEnabled,value=>{if(value!==undefined)sprint.value=value;});
const torchGesture=new TorchGesture(),adjustingTorch=ref(false);
function lightStart(event){event.preventDefault();event.stopPropagation();if(torchGesture.start(event.pointerId,event.clientY,props.hud.flashlightBrightness||1))event.currentTarget.setPointerCapture(event.pointerId);}
function lightMove(event){const value=torchGesture.move(event.pointerId,event.clientY);if(value===null)return;event.preventDefault();adjustingTorch.value=true;props.engine.setTorchBrightness(value,false);}
function lightEnd(event){const dragged=torchGesture.end(event.pointerId);if(dragged===null)return;adjustingTorch.value=false;if(event.type==='pointerup'){if(dragged)props.engine.commitTorchBrightness();else action('light');}else if(dragged)props.engine.commitTorchBrightness();}
function lightKey(event){if(event.key==='ArrowUp'||event.key==='ArrowDown'){event.preventDefault();props.engine.setTorchBrightness((props.hud.flashlightBrightness||1)+(event.key==='ArrowUp'?.1:-.1));}}
let firePointer=null,lastFire=null,moveOrigin=null;const moveGesture=new MoveGesture((f,s)=>props.engine?.setTouchMove(f,s));
const lookGesture=new LookGesture({look:(x,y)=>props.engine.lookTouch(x,y),zoom:ratio=>props.engine.zoomTouch(ratio)});
function move(event){event.preventDefault();const origin=moveOrigin;if(!origin)return;const v=moveGesture.move(event.pointerId,event.clientX-origin.x,event.clientY-origin.y,event);knob.value=v?{x:v.x,y:v.y}:moveGesture.pointer===null?{x:0,y:0}:knob.value;}
function moveStart(event){event.preventDefault();if(moveGesture.start(event.pointerId,()=>event.currentTarget.setPointerCapture(event.pointerId))){const r=event.currentTarget.getBoundingClientRect();moveOrigin={x:r.left+r.width/2,y:r.top+r.height/2};move(event);}}
function moveEnd(event){if(moveGesture.end(event.pointerId)){moveOrigin=null;knob.value={x:0,y:0};}}
function touchStart(event){if(event.changedTouches?.length)moveGesture.trackTouch(event.changedTouches[0].identifier);}
function touchRelease(event){if(moveGesture.releaseTouches(Array.from(event.changedTouches||[],t=>t.identifier),event.touches?.length||0)){moveOrigin=null;knob.value={x:0,y:0};}}
function visibilityReset(){if(document.hidden)resetGestures();}
let viewportWidth=typeof window!=='undefined'?window.innerWidth:0,landscape=typeof window!=='undefined'?window.innerWidth>=window.innerHeight:true;
function viewportChanged(){const width=window.innerWidth,nextLandscape=width>=window.innerHeight;const changed=Math.abs(width-viewportWidth)>32||nextLandscape!==landscape;viewportWidth=width;landscape=nextLandscape;if(changed)resetGestures();}

function lookStart(event){event.preventDefault();if(lookGesture.start(event.pointerId,event.clientX,event.clientY)){looking.value=true;event.currentTarget.setPointerCapture(event.pointerId);}}
function lookMove(event){if(!lookGesture.points.has(event.pointerId))return;event.preventDefault();lookGesture.move(event.pointerId,event.clientX,event.clientY);}
function lookEnd(event){lookGesture.end(event.pointerId);looking.value=lookGesture.points.size>0;}
function fireStart(event){if(firePointer!==null)return;event.preventDefault();event.stopPropagation();firePointer=event.pointerId;lastFire={x:event.clientX,y:event.clientY};event.currentTarget.setPointerCapture(event.pointerId);props.engine.requestTouchShot();}
function fireMove(event){if(event.pointerId!==firePointer)return;event.preventDefault();props.engine.lookTouch(event.clientX-lastFire.x,event.clientY-lastFire.y);lastFire={x:event.clientX,y:event.clientY};}
function fireEnd(event){if(event.pointerId===firePointer){firePointer=null;lastFire=null;}}
function keyboardFire(event){if(event.detail===0)props.engine.requestTouchShot();}
function buttonAction(event,name){if(event.type==='pointerdown'||event.detail===0)action(name);}
function toolAction(event,name){event.stopPropagation();emit(name);}
function action(name){nativeFeedback();if(name==='aim')props.engine.toggleAim();else if(name==='draw')props.engine.toggleWeapon();else if(name==='weapon')props.engine.switchWeapon();else if(name==='mask')props.engine.toggleMask();else if(name==='run'){sprint.value=!sprint.value;props.engine.touchInput.sprint=sprint.value;}else if(name==='hide'){props.engine.toggleHide();}else if(name==='crouch'){crouch.value=!crouch.value;props.engine.touchInput.crouch=crouch.value;}else if(name==='use')props.engine.interact();else if(name==='light')props.engine.toggleFlash();else if(name==='reload')props.engine.reload();}
function resetGestures(){if(torchGesture.dragged)props.engine?.commitTorchBrightness();torchGesture.reset();adjustingTorch.value=false;moveGesture.reset();moveOrigin=null;firePointer=null;lastFire=null;lookGesture.reset();knob.value={x:0,y:0};looking.value=sprint.value=crouch.value=false;props.engine?.resetTouch();}
watch(()=>props.engine?.paused,value=>{if(value)resetGestures();});
onMounted(()=>{window.addEventListener('pointerup',moveEnd,true);window.addEventListener('pointercancel',moveEnd,true);window.addEventListener('touchend',touchRelease,true);window.addEventListener('touchcancel',touchRelease,true);window.addEventListener('pagehide',resetGestures);document.addEventListener('visibilitychange',visibilityReset);window.addEventListener('resize',viewportChanged);window.addEventListener('blur',resetGestures);window.visualViewport?.addEventListener('resize',viewportChanged);});
onBeforeUnmount(()=>{window.removeEventListener('pointerup',moveEnd,true);window.removeEventListener('pointercancel',moveEnd,true);window.removeEventListener('touchend',touchRelease,true);window.removeEventListener('touchcancel',touchRelease,true);window.removeEventListener('pagehide',resetGestures);document.removeEventListener('visibilitychange',visibilityReset);window.removeEventListener('resize',viewportChanged);window.removeEventListener('blur',resetGestures);window.visualViewport?.removeEventListener('resize',viewportChanged);resetGestures();});
</script>
<template>
  <div class="phone-controls">
    <div class="phone-look" :class="{looking}" data-testid="touch-look" aria-label="Drag to look around; pinch with two fingers to zoom" @pointerdown="lookStart" @pointermove="lookMove" @pointerup="lookEnd" @pointercancel="lookEnd" @lostpointercapture="lookEnd"><span>DRAG TO LOOK · PINCH TO ZOOM</span></div>
    <nav class="phone-tools" aria-label="Mission tools"><button v-if="hud.cover" class="peek-control" :aria-pressed="!!hud.peeking" aria-label="Peek from cover" @pointerdown.prevent="engine.setPeek(true);$event.currentTarget.setPointerCapture($event.pointerId)" @pointerup.prevent="engine.setPeek(false)" @pointercancel="engine.setPeek(false)" @lostpointercapture="engine.setPeek(false)"><Eye :size="20"/><small>PEEK</small></button><button aria-label="Hospital map" @pointerdown.stop @click="toolAction($event,'map')"><Map :size="19"/></button><button :aria-label="hud.assignment?.photoOnly||hud.assignment?.infiltration?'Evidence journal':'Clue journal'" @pointerdown.stop @click="toolAction($event,'journal')"><BookOpen :size="19"/></button><button aria-label="Pause mission" @pointerdown.stop @click="toolAction($event,'pause')"><Pause :size="19"/></button></nav>
    <div class="phone-move" data-testid="touch-move" aria-label="Movement joystick" @touchstart.passive="touchStart" @pointerdown="moveStart" @pointermove="move" @pointerup="moveEnd" @pointercancel="moveEnd" @lostpointercapture="moveEnd"><span class="stick-cross">+</span><span class="stick-knob" :style="{transform:`translate(${knob.x}px,${knob.y}px)`}"></span><small>MOVE</small></div>
    <div class="phone-stance"><button aria-label="Toggle sprint" :aria-pressed="sprint" :class="{active:sprint}" @pointerdown.prevent="buttonAction($event,'run')" @click="buttonAction($event,'run')"><Footprints :size="18"/><small>RUN</small></button><button aria-label="Toggle duck" :aria-pressed="crouch" :class="{active:crouch}" @pointerdown.prevent="buttonAction($event,'crouch')" @click="buttonAction($event,'crouch')"><ArrowDown :size="18"/><small>DUCK</small></button><button aria-label="Hide behind cover" :aria-pressed="hud.hiding" :class="{active:hud.hiding}" @pointerdown.prevent="buttonAction($event,'hide')" @click="buttonAction($event,'hide')"><Shield :size="18"/><small>HIDE</small></button></div>
    <div class="phone-gear"><button v-if="!hud.assignment?.unarmed" :aria-label="hud.assignment?.photoOnly?'Raise camera':hud.weaponDrawn?'Holster weapon':'Draw weapon'" :class="{active:hud.weaponDrawn}" @pointerdown.prevent="buttonAction($event,'draw')" @click="buttonAction($event,'draw')"><Crosshair :size="16"/><small>{{hud.assignment?.photoOnly?'CAMERA':hud.weaponDrawn?'HOLSTER':'DRAW'}}</small></button><button v-if="!hud.assignment?.photoOnly && !hud.assignment?.unarmed" aria-label="Switch weapon" @pointerdown.prevent="buttonAction($event,'weapon')" @click="buttonAction($event,'weapon')"><Target :size="16"/><small>{{hud.weaponKind==='sniper'?'PISTOL':'RIFLE'}}</small></button><button aria-label="Toggle mask" :class="{active:hud.masked}" @pointerdown.prevent="buttonAction($event,'mask')" @click="buttonAction($event,'mask')"><Shield :size="16"/><small>MASK</small></button></div>
    <div class="phone-actions">
      <button class="phone-use" data-testid="touch-use" aria-label="Interact" :class="{available:hud.prompt}" @pointerdown.prevent="buttonAction($event,'use')" @click="buttonAction($event,'use')"><Hand :size="21"/><small>USE</small></button>
      <button v-if="!hud.assignment?.unarmed" data-testid="touch-aim" aria-label="Toggle aim" :aria-pressed="hud.aiming" :class="{active:hud.aiming}" @pointerdown.prevent="buttonAction($event,'aim')" @click="buttonAction($event,'aim')"><Crosshair :size="22"/><small>AIM</small></button>
      <button v-if="!hud.assignment?.unarmed" class="phone-fire" data-testid="touch-fire" :aria-label="hud.assignment?.photoOnly?'Take evidence photograph':'Fire weapon'" @pointerdown="fireStart" @pointermove="fireMove" @pointerup="fireEnd" @pointercancel="fireEnd" @lostpointercapture="fireEnd" @click="keyboardFire"><Target :size="28"/><small>{{hud.assignment?.photoOnly?'PHOTO':'FIRE'}}</small><b>{{hud.assignment?.photoOnly?`${hud.assignment.photos.length}/3`:hud.ammo}}</b></button>
      <button class="phone-light" data-testid="touch-light" :aria-label="`Flashlight ${Math.round((hud.flashlightBrightness||1)/2.5*100)} percent. Tap to toggle, drag up or down to adjust brightness`" :aria-pressed="hud.flashlight" :class="{active:hud.flashlight,adjusting:adjustingTorch}" @pointerdown="lightStart" @pointermove="lightMove" @pointerup="lightEnd" @pointercancel="lightEnd" @lostpointercapture="lightEnd" @keydown="lightKey" @click="buttonAction($event,'light')"><Flashlight :size="20"/><small>{{adjustingTorch?`${Math.round((hud.flashlightBrightness||1)/2.5*100)}%`:'LIGHT ↕'}}</small><output v-if="adjustingTorch" class="torch-level">{{Math.round((hud.flashlightBrightness||1)/2.5*100)}}%<small>BRIGHTNESS</small></output></button>
      <button v-if="!hud.assignment?.photoOnly && !hud.assignment?.unarmed" data-testid="touch-reload" aria-label="Reload weapon" @pointerdown.prevent="buttonAction($event,'reload')" @click="buttonAction($event,'reload')"><RotateCcw :size="20"/><small>{{hud.reloading?'LOADING':'RELOAD'}}</small></button>
    </div>
  </div>
</template>
